#[derive(Debug, Default)]
pub struct WhitespaceControlled {
    base: ARObject,
    xml_space: Option<XmlSpace>,
}

impl WhitespaceControlled {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn base(&self) -> &ARObject {
        &self.base
    }

    pub fn base_mut(&mut self) -> &mut ARObject {
        &mut self.base
    }

    pub fn get_xml_space(&self) -> Option<XmlSpace> {
        self.xml_space
    }

    pub fn set_xml_space(&mut self, value: XmlSpace) -> &mut Self {
        self.xml_space = Some(value);
        self
    }

    pub fn get_checksum(&self) -> Option<&str> {
        self.base().get_checksum()
    }

    pub fn set_checksum(&mut self, value: impl Into<String>) -> &mut Self {
        self.base_mut().set_checksum(value);
        self
    }

    pub fn get_timestamp(&self) -> Option<&str> {
        self.base().get_timestamp()
    }

    pub fn set_timestamp(&mut self, value: impl Into<String>) -> &mut Self {
        self.base_mut().set_timestamp(value);
        self
    }
}
impl Document {
    pub(crate) fn compare_l_long_name(
        &self,
        other: &Document,
        a: &LLongName,
        b: &LLongName,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_long_name(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        if a.get_blueprint_value() != b.get_blueprint_value() {
            return Err(format!("{path}: BLUEPRINT_VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_l_overview_paragraph(
        &self,
        other: &Document,
        a: &LOverviewParagraph,
        b: &LOverviewParagraph,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_overview_paragraph(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        if a.get_blueprint_value() != b.get_blueprint_value() {
            return Err(format!("{path}: BLUEPRINT_VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_l_paragraph(
        &self,
        other: &Document,
        a: &LParagraph,
        b: &LParagraph,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_paragraph(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        Ok(())
    }

    pub(crate) fn compare_l_plain_text(
        &self,
        other: &Document,
        a: &LPlainText,
        b: &LPlainText,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_plain_text(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        Ok(())
    }

    pub(crate) fn compare_l_verbatim(
        &self,
        other: &Document,
        a: &LVerbatim,
        b: &LVerbatim,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_verbatim(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        Ok(())
    }

    pub(crate) fn compare_language_specific(
        &self,
        _other: &Document,
        a: &LanguageSpecific,
        b: &LanguageSpecific,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_l() != b.get_l() {
            return Err(format!("{path}: L mismatch"));
        }
        if a.get_value() != b.get_value() {
            return Err(format!("{path}: VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_long_name(
        &self,
        other: &Document,
        a: &MixedContentForLongName,
        b: &MixedContentForLongName,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        self.compare_atp_mixed_string(other, a.atp_mixed_string(), b.atp_mixed_string(), path)?;
        if a.get_e() != b.get_e() {
            return Err(format!("{path}: E mismatch"));
        }
        if a.get_ie() != b.get_ie() {
            return Err(format!("{path}: IE mismatch"));
        }
        if a.get_sub() != b.get_sub() {
            return Err(format!("{path}: SUB mismatch"));
        }
        if a.get_sup() != b.get_sup() {
            return Err(format!("{path}: SUP mismatch"));
        }
        if a.get_tt() != b.get_tt() {
            return Err(format!("{path}: TT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_overview_paragraph(
        &self,
        other: &Document,
        a: &MixedContentForOverviewParagraph,
        b: &MixedContentForOverviewParagraph,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        self.compare_atp_mixed_string(other, a.atp_mixed_string(), b.atp_mixed_string(), path)?;
        if a.get_br() != b.get_br() {
            return Err(format!("{path}: BR mismatch"));
        }
        if a.get_e() != b.get_e() {
            return Err(format!("{path}: E mismatch"));
        }
        if a.get_ft() != b.get_ft() {
            return Err(format!("{path}: FT mismatch"));
        }
        if a.get_ie() != b.get_ie() {
            return Err(format!("{path}: IE mismatch"));
        }
        if a.get_sub() != b.get_sub() {
            return Err(format!("{path}: SUB mismatch"));
        }
        if a.get_sup() != b.get_sup() {
            return Err(format!("{path}: SUP mismatch"));
        }
        if a.get_trace_ref() != b.get_trace_ref() {
            return Err(format!("{path}: TRACE_REF mismatch"));
        }
        if a.get_tt() != b.get_tt() {
            return Err(format!("{path}: TT mismatch"));
        }
        if a.get_xref() != b.get_xref() {
            return Err(format!("{path}: XREF mismatch"));
        }
        if a.get_xref_target() != b.get_xref_target() {
            return Err(format!("{path}: XREF_TARGET mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_paragraph(
        &self,
        _other: &Document,
        a: &MixedContentForParagraph,
        b: &MixedContentForParagraph,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_br() != b.get_br() {
            return Err(format!("{path}: BR mismatch"));
        }
        if a.get_e() != b.get_e() {
            return Err(format!("{path}: E mismatch"));
        }
        if a.get_ft() != b.get_ft() {
            return Err(format!("{path}: FT mismatch"));
        }
        if a.get_ie() != b.get_ie() {
            return Err(format!("{path}: IE mismatch"));
        }
        if a.get_std() != b.get_std() {
            return Err(format!("{path}: STD mismatch"));
        }
        if a.get_sub() != b.get_sub() {
            return Err(format!("{path}: SUB mismatch"));
        }
        if a.get_sup() != b.get_sup() {
            return Err(format!("{path}: SUP mismatch"));
        }
        if a.get_trace_ref() != b.get_trace_ref() {
            return Err(format!("{path}: TRACE_REF mismatch"));
        }
        if a.get_tt() != b.get_tt() {
            return Err(format!("{path}: TT mismatch"));
        }
        if a.get_xdoc() != b.get_xdoc() {
            return Err(format!("{path}: XDOC mismatch"));
        }
        if a.get_xfile() != b.get_xfile() {
            return Err(format!("{path}: XFILE mismatch"));
        }
        if a.get_xref() != b.get_xref() {
            return Err(format!("{path}: XREF mismatch"));
        }
        if a.get_xref_target() != b.get_xref_target() {
            return Err(format!("{path}: XREF_TARGET mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_plain_text(
        &self,
        other: &Document,
        a: &MixedContentForPlainText,
        b: &MixedContentForPlainText,
        path: &str,
    ) -> Result<(), String> {
        self.compare_whitespace_controlled(other, a.base(), b.base(), path)?;
        self.compare_atp_mixed_string(other, a.atp_mixed_string(), b.atp_mixed_string(), path)?;
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_unit_names(
        &self,
        other: &Document,
        a: &MixedContentForUnitNames,
        b: &MixedContentForUnitNames,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        self.compare_atp_mixed_string(other, a.atp_mixed_string(), b.atp_mixed_string(), path)?;
        if a.get_sub() != b.get_sub() {
            return Err(format!("{path}: SUB mismatch"));
        }
        if a.get_sup() != b.get_sup() {
            return Err(format!("{path}: SUP mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mixed_content_for_verbatim(
        &self,
        other: &Document,
        a: &MixedContentForVerbatim,
        b: &MixedContentForVerbatim,
        path: &str,
    ) -> Result<(), String> {
        self.compare_whitespace_controlled(other, a.base(), b.base(), path)?;
        self.compare_atp_mixed_string(other, a.atp_mixed_string(), b.atp_mixed_string(), path)?;
        if a.get_br() != b.get_br() {
            return Err(format!("{path}: BR mismatch"));
        }
        if a.get_e() != b.get_e() {
            return Err(format!("{path}: E mismatch"));
        }
        if a.get_tt() != b.get_tt() {
            return Err(format!("{path}: TT mismatch"));
        }
        if a.get_xref() != b.get_xref() {
            return Err(format!("{path}: XREF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sl_paragraph(
        &self,
        other: &Document,
        a: &SlParagraph,
        b: &SlParagraph,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_paragraph(other, a.base(), b.base(), path)?;
        self.compare_language_specific(other, a.language_specific(), b.language_specific(), path)?;
        Ok(())
    }

    pub(crate) fn compare_whitespace_controlled(
        &self,
        _other: &Document,
        a: &WhitespaceControlled,
        b: &WhitespaceControlled,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_xml_space() != b.get_xml_space() {
            return Err(format!("{path}: XML_SPACE mismatch"));
        }
        Ok(())
    }
}
